#include "93t4hhsr.vcd/Ecommerce/MercadoLibre.js"	// Sygemat_Corralon_dat


// --------------------------------------------------------------------------------
// Cargar el combobox de estados añadiendo la opción "Todos"
// --------------------------------------------------------------------------------
importClass("VImage");

// --------------------------------------------------------------------------------
// Preparamos el control combobox
// --------------------------------------------------------------------------------
var combobox = theRoot.dataView().control("DSC");
combobox.clear(); // Limpiamos las opciones del comboBox


var nomcat 			=  theRoot.varToString("NOM_CAT");
var catid  			=  theRoot.varToString("CAT_ID");

// --------------------------------------------------------------------------------
// Verificamos si las variables catid y nomcat tienen valores
// --------------------------------------------------------------------------------
if (nomcat && catid) {
    // Añadimos el valor de las variables al combobox
    combobox.addItem(nomcat, catid);

} else {

	// --------------------------------------------------------------------------------
	// Obtenemos la categoría usando el título
	// --------------------------------------------------------------------------------
	var titulo = theRoot.varToString("TIT"); // Obtenemos el título desde una variable
	var categorias = BuscarCategoria(titulo); // Llamamos a la función BuscarCategorias

	// --------------------------------------------------------------------------------
	// Verificamos que existan categorías antes de procesar
	// --------------------------------------------------------------------------------
	if (categorias.length > 0) {
		// Recorremos cada categoría del array y las añadimos al comboBox
		categorias.forEach(function(categoria) {
			combobox.addItem(categoria.categoryName, categoria.categoryId);
		});
	} else {
		// Alerta si no hay categorías encontradas
		//alert("No se encontraron categorías para el título proporcionado.");
	}
}

// Leer la opción seleccionada del combobox Descripcion y guardarla en la variable local del formulario
theRoot.setVar("DSC", "");
var combobox = theRoot.dataView().control("DSC");
var itemId = combobox.itemData(combobox.currentIndex);
var findData = combobox.findData(itemId);
var itemText = combobox.itemText(findData);

//alert("LEER el item id es: " + itemId + " LEER el item text: " + itemText);

if (itemText)
{
	theRoot.setVar("NOM_CAT", itemText);

	//Seteo el id de variable para que cargue la opcion correcta
	theRoot.setVar("CAT_ID", itemId);

};
